// ---------------------------------------------------------------------------
// Loader for the static illustrative Reddit/Discord sample.
//
// PROVENANCE, PLAINLY: every row this module returns is SYNTHETIC. It was
// generated by scripts/generate_synthetic.py to exercise the pipeline while
// Reddit was unreachable and no Discord access existed. It is not observed
// data and must never be presented as measurement.
//
// It is still loaded by default so the dashboard demonstrates a full-looking
// tool, but every row is stamped `data_type: "sample"` and carries
// `is_sample: true`, the API reports the share of the dataset it represents,
// and the UI tags it on every surface it appears on. Set DEMO_DATA=false to
// drop it entirely and run on collected data only.
//
// The sample's original free-text theme labels are mapped onto the controlled
// vocabulary in lib/nlp.js, so sample and live rows aggregate into the same
// theme chart instead of splitting into two near-duplicate label sets.
// ---------------------------------------------------------------------------

const fs = require("fs");
const path = require("path");
const { parse } = require("csv-parse/sync");
const { analyzeSentiment } = require("./sentiment");
const { engagementIndex } = require("./engagement");

const SYNTHETIC_CSV = path.join(__dirname, "..", "..", "data", "processed", "synthetic_reddit_discord.csv");

// Legacy free-text theme → controlled vocabulary (see lib/nlp.js THEMES).
const THEME_MAP = {
  praise: "praise",
  "build/base building praise": "praise",
  "open world praise": "story & world",
  "questline/story praise": "story & world",
  "netcode/matchmaking": "matchmaking & netcode",
  "matchmaking/queue": "matchmaking & netcode",
  monetization: "monetization",
  "monetization concerns": "monetization",
  "monetization/gacha": "monetization",
  "subscription/monetization": "monetization",
  bugs: "bugs & technical issues",
  "server queue/launch issues": "bugs & technical issues",
  "bug/cheating complaints": "cheating & fair play",
  "new character hype": "character & roster",
  "comic/crossover speculation": "new content & updates",
  "crossover hype": "new content & updates",
  "expansion skepticism": "new content & updates",
  "new content questions": "new content & updates",
  "console launch anticipation": "platform & availability",
  "ranked complaints": "esports & competitive",
  "pvp season": "esports & competitive",
  "class balance": "game balance",
  "mode feedback": "game balance",
  "balance patch reaction": "game balance",
  "community questions": "community & social",
  "server/season fatigue": "grind & progression",
  nostalgia: "nostalgia",
  "nostalgia/nostalgia fatigue": "nostalgia",
  comparisons: "other",
};

let cached = null;

function loadSampleRows() {
  if (cached) return cached;

  let raw;
  try {
    raw = fs.readFileSync(SYNTHETIC_CSV, "utf-8");
  } catch (err) {
    // Missing sample file is not fatal — the tool runs on live data alone.
    cached = [];
    return cached;
  }

  const records = parse(raw, { columns: true, skip_empty_lines: true });

  cached = records.map((r) => {
    const sentiment = analyzeSentiment(r.text);
    const base = {
      platform: r.platform,
      data_type: "sample",
      is_sample: true,
      game: r.game,
      source: r.source,
      content_type: r.content_type,
      author: r.author,
      timestamp: r.timestamp,
      text: r.text,
      theme: THEME_MAP[r.theme] || "other",
      theme_original: r.theme || "",
      score: Number(r.score || 0),
      num_comments: Number(r.num_comments || 0),
      url: r.url || "",
      sentiment_score: sentiment.score,
      sentiment_label: sentiment.label,
      sentiment_confidence: sentiment.confidence,
      sentiment_method: "lexicon",
      sarcasm: false,
      is_question: (r.text || "").trim().endsWith("?"),
      is_risk: false,
      language: "en",
      region: "Undetermined",
      region_source: "none",
      region_confidence: 0,
    };
    base.engagement_index = engagementIndex(base);
    return base;
  });

  return cached;
}

/** Back-compat alias — the original name used elsewhere in the codebase. */
const loadSyntheticRows = loadSampleRows;

module.exports = { loadSampleRows, loadSyntheticRows, THEME_MAP };
